@@ -0,0 +1,22 @@
+#pragma once
+
+#include "shape.hpp"
+#include <stdexcept>
+#include <cmath>
+
+namespace geometry {
+
+class Triangle : public Shape {
+public:
+    // 建構子：接受三邊長
+    Triangle(double a, double b, double c);
+
+    // 實作 Shape 介面
+    std::string name() const override;
+    double area() const override;
+
+private:
+    double sideA, sideB, sideC;
+};
+
+} // namespace geometry

--- a/src/registry.cpp
+++ b/src/registry.cpp
@@ -5,6 +5,7 @@

 #include "geometry/circle.hpp"
 #include "geometry/rectangle.hpp"
+#include "geometry/triangle.hpp"

 namespace geometry {

@@ -27,6 +28,13 @@
             throw std::invalid_argument("rect needs width and height: " + line);
         }
         return std::make_unique<Rectangle>(w, h);
+    }
+    if (kind == "triangle") {
+        double a = 0, b = 0, c = 0;
+        if (!(in >> a >> b >> c)) {
+            throw std::invalid_argument("triangle needs three side lengths: " + line);
+        }
+        return std::make_unique<Triangle>(a, b, c);
     }
     throw std::invalid_argument("unknown shape: " + kind);
 }

--- a/src/triangle.cpp
+++ b/src/triangle.cpp
@@ -0,0 +1,28 @@
+#include "geometry/triangle.hpp"
+#include "geometry/shape.hpp"
+#include <cmath>
+#include <stdexcept>
+
+namespace geometry {
+
+Triangle::Triangle(double a, double b, double c) : sideA(a), sideB(b), sideC(c) {
+    if (a <= 0 || b <= 0 || c <= 0) {
+        throw std::invalid_argument("Triangle sides must be positive.");
+    }
+    // Triangle inequality check
+    if (a + b <= c || a + c <= b || b + c <= a) {
+        throw std::invalid_argument("Sides do not form a valid triangle.");
+    }
+}
+
+double Triangle::area() const {
+    // Heron's formula
+    double s = (sideA + sideB + sideC) / 2.0;
+    return std::sqrt(s * (s - sideA) * (s - sideB) * (s - sideC));
+}
+
+std::string Triangle::name() const {
+    return "triangle";
+}
+
+} // namespace geometry

--- a/tests/test_shapes.cpp
+++ b/tests/test_shapes.cpp
@@ -5,9 +5,11 @@

 #include "geometry/circle.hpp"
 #include "geometry/rectangle.hpp"
+#include "geometry/triangle.hpp"

 using geometry::Circle;
 using geometry::Rectangle;
+using geometry::Triangle;

 TEST(CircleTest, Area) {
     Circle c(2.0);
@@ -30,3 +32,21 @@
     EXPECT_THROW(Rectangle(0.0, 1.0), std::invalid_argument);
     EXPECT_THROW(Rectangle(1.0, -2.0), std::invalid_argument);
 }
+
+TEST(TriangleTest, Area) {
+    // 3, 4, 5 is a right triangle, area = 0.5 * 3 * 4 = 6.0
+    Triangle t(3.0, 4.0, 5.0);
+    EXPECT_NEAR(t.area(), 6.0, 1e-9);
+    EXPECT_EQ(t.name(), "triangle");
+}
+
+TEST(TriangleTest, RejectsInvalidSides) {
+    // Zero side
+    EXPECT_THROW(Triangle(0.0, 4.0, 5.0), std::invalid_argument);
+    // Negative side
+    EXPECT_THROW(Triangle(3.0, -4.0, 5.0), std::invalid_argument);
+    // Triangle inequality violation (1 + 2 <= 5)
+    EXPECT_THROW(Triangle(1.0, 2.0, 5.0), std::invalid_argument);
+    // Triangle inequality violation (1 + 1 <= 3)
+    EXPECT_THROW(Triangle(1.0, 1.0, 3.0), std::invalid_argument);
+}

