@@ -41,3 +41,87 @@
     rb_push(&rb, 4.0);
     EXPECT_DOUBLE_EQ(rb_mean(&rb), 3.0);
 }
+
+TEST_F(RingBufTest, ClearResetsState) {
+    rb_push(&rb, 10.0);
+    rb_push(&rb, 20.0);
+    
+    // Check initial state
+    EXPECT_EQ(rb_size(&rb), 2u);
+    
+    // Clear the buffer
+    rb_clear(&rb);
+    
+    // Check state after clearing
+    EXPECT_EQ(rb_size(&rb), 0u);
+    // Head should be reset to 0, capacity should remain 3
+    // We can't directly check head without exposing it, but we can check if subsequent operations work as expected for an empty buffer.
+    
+    // Test that it's empty
+    double v = 0;
+    EXPECT_FALSE(rb_pop(&rb, &v));
+    
+    // Test that we can push again and it works
+    rb_push(&rb, 5.0);
+    EXPECT_EQ(rb_size(&rb), 1u);
+    
+    // Test that capacity is unchanged (by pushing more than capacity)
+    rb_push(&rb, 6.0);
+    rb_push(&rb, 7.0);
+    rb_push(&rb, 8.0);
+    EXPECT_TRUE(rb_is_full(&rb));
+    EXPECT_EQ(rb_size(&rb), 3u);
+}
+
+TEST_F(RingBufTest, ClearFunctionality) {
+    // 1. Push values to make it non-empty
+    rb_push(&rb, 10.0);
+    rb_push(&rb, 20.0);
+    rb_push(&rb, 30.0);
+    EXPECT_EQ(rb_size(&rb), 3u);
+
+    // 2. Clear the buffer
+    rb_clear(&rb);
+
+    // 3. Verify size is 0 and pop returns false
+    EXPECT_EQ(rb_size(&rb), 0u);
+    double v_pop = 0.0;
+    EXPECT_FALSE(rb_pop(&rb, &v_pop));
+
+    // 4. Verify it can be pushed and popped again
+    rb_push(&rb, 99.0);
+    EXPECT_EQ(rb_size(&rb), 1u);
+    
+    double v_pop_after_clear = 0.0;
+    ASSERT_TRUE(rb_pop(&rb, &v_pop_after_clear));
+    EXPECT_DOUBLE_EQ(v_pop_after_clear, 99.0);
+    EXPECT_EQ(rb_size(&rb), 0u);
+}
+
+TEST_F(RingBufTest, PeekOldestEmpty) {
+    double v = 0.0;
+    EXPECT_FALSE(rb_peek_oldest(&rb, &v));
+    // Ensure state is unchanged
+    EXPECT_EQ(rb_size(&rb), 0u);
+}
+
+TEST_F(RingBufTest, PeekOldestSuccess) {
+    // Push values: 1.0 (oldest), 2.0, 3.0
+    rb_push(&rb, 1.0);
+    rb_push(&rb, 2.0);
+    rb_push(&rb, 3.0);
+
+    // Peek oldest (should be 1.0)
+    double peeked_value = 0.0;
+    ASSERT_TRUE(rb_peek_oldest(&rb, &peeked_value));
+    EXPECT_DOUBLE_EQ(peeked_value, 1.0);
+
+    // Verify state is unchanged (count should still be 3)
+    EXPECT_EQ(rb_size(&rb), 3u);
+
+    // Pop to verify 1.0 was indeed the oldest
+    double popped_value = 0.0;
+    ASSERT_TRUE(rb_pop(&rb, &popped_value));
+    EXPECT_DOUBLE_EQ(popped_value, 1.0);
+    EXPECT_EQ(rb_size(&rb), 2u);
+}

