+  // Pose A at origin, Pose B translates 1 unit along X in A's frame
+  Pose2D a = Pose2D{0.0, 0.0, 0.0};
+  Pose2D b = Pose2D{1.0, 0.0, 0.0};
+  Pose2D result = amr_utils::compose(a, b);
+  EXPECT_NEAR(result.x, 1.0, 1e-9);
