+}
+
+TEST(Compose, SimpleRotation) {
+  // Pose A at origin, Pose B rotates 90 degrees (pi/2) in A's frame
+  Pose2D a = Pose2D{0.0, 0.0, 0.0};
+  Pose2D b = Pose2D{0.0, 1.0, M_PI / 2.0};
+  Pose2D result = amr_utils::compose(a, b);
+  // Expected: x = 0 + cos(0)*0 - sin(0)*1 = 0
+  //           y = 0 + sin(0)*0 + cos(0)*1 = 1
+  //           theta = 0 + pi/2 = pi/2
+  EXPECT_NEAR(result.x, 0.0, 1e-9);
+  EXPECT_NEAR(result.y, 1.0, 1e-9);
+  EXPECT_NEAR(result.theta, M_PI / 2.0, 1e-9);
+}
+
+TEST(Compose, TranslationAfterRotation) {
+  // Pose A at (0,0) facing 90 degrees (pi/2).
+  Pose2D a = Pose2D{0.0, 0.0, M_PI / 2.0};
+  // Pose B translates 1 unit along its local X-axis (which is world Y-axis)
+  Pose2D b = Pose2D{1.0, 0.0, 0.0};
+  Pose2D result = amr_utils::compose(a, b);
+  // Expected: World translation of 1 unit along Y axis.
+  // x = 0 + cos(pi/2)*1 - sin(pi/2)*0 = 0 + 0*1 - 1*0 = 0
+  // y = 0 + sin(pi/2)*1 + cos(pi/2)*0 = 0 + 1*1 + 0*0 = 1
+  // theta = pi/2 + 0 = pi/2
+  EXPECT_NEAR(result.x, 0.0, 1e-9);
+  EXPECT_NEAR(result.y, 1.0, 1e-9);
+  EXPECT_NEAR(result.theta, M_PI / 2.0, 1e-9);
+}
