+TEST(Compose, RotationAfterTranslation) {
+  // Pose A at (1,0) facing 0 degrees.
+  Pose2D a = Pose2D{1.0, 0.0, 0.0};
+  // Pose B rotates 90 degrees (pi/2) in A's frame.
+  Pose2D b = Pose2D{0.0, 0.0, M_PI / 2.0};
+  Pose2D result = amr_utils::compose(a, b);
+  // Expected: World position (1,0), World rotation pi/2.
+  // x = 1 + cos(0)*0 - sin(0)*0 = 1
+  // y = 0 + sin(0)*0 + cos(0)*0 = 0
+  // theta = 0 + pi/2 = pi/2
+  EXPECT_NEAR(result.x, 1.0, 1e-9);
+  EXPECT_NEAR(result.y, 0.0, 1e-9);
+  EXPECT_NEAR(result.theta, M_PI / 2.0, 1e-9);
+}
